package com.accessaudit.security;
import com.accessaudit.repo.AdminAccountRepository; import org.springframework.context.annotation.*; import org.springframework.security.authentication.*; import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.security.web.context.HttpSessionSecurityContextRepository; import org.springframework.security.web.context.SecurityContextRepository;
@Configuration @EnableMethodSecurity
public class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean UserDetailsService userDetailsService(AdminAccountRepository accounts){return username->{var a=accounts.findByUsernameIgnoreCase(username).orElseThrow(()->new UsernameNotFoundException("Usuário não encontrado."));if(!a.isActive())throw new DisabledException("Conta desativada.");return User.withUsername(a.getUsername()).password(a.getPasswordHash()).roles(a.getRole()).build();};}
 @Bean AuthenticationManager authenticationManager(AuthenticationConfiguration config)throws Exception{return config.getAuthenticationManager();}
 @Bean SecurityContextRepository securityContextRepository(){return new HttpSessionSecurityContextRepository();}
 @Bean SecurityFilterChain filterChain(HttpSecurity http,SecurityContextRepository repository)throws Exception{return http.securityContext(context->context.securityContextRepository(repository)).csrf(csrf->csrf.disable()).authorizeHttpRequests(auth->auth.requestMatchers("/api/auth/login","/api/auth/logout").permitAll().requestMatchers("/api/**").authenticated().anyRequest().permitAll()).exceptionHandling(ex->ex.authenticationEntryPoint((req,res,e)->res.sendError(401))).formLogin(form->form.disable()).httpBasic(basic->basic.disable()).logout(logout->logout.disable()).build();}
}
